import json

repos = ['atlas','beacon','cinder']
found = []
for repo in repos:
    offset = 0
    while True:
        r = list_issues(repo=repo, limit=50, offset=offset)
        items = r.get('items', [])
        for it in items:
            iid = it['id']
            full = get_issue(iid)
            for c in full.get('comments', []):
                if 'zx56083' in c:
                    found.append((repo, iid, full.get('assignee'), full.get('title')))
        if len(items) < 50:
            break
        offset += 50
print(json.dumps(found, indent=2))

